   while (!stopRequested) {
     const active = await tick();
     await sleep(active ? TICK_MS : IDLE_TICK_MS);
   }
   petRef?.clearRow();
 }

 export function initEngine(pet: Pet): void {
   if (petRef) return;
   petRef = pet;
   stopRequested = false;
   lastMoveTs = Date.now();
   mood = "idle";
   sleeping = false;
   void loop();
